<?php $edit = $sectionData['edit'] ?? null; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Public service pages</span><h2><?= $edit ? 'Edit service' : 'Add a service' ?></h2><p>Active services are shown on the public services page.</p></div></div>
  <form class="admin-form-card" method="post" action="<?= $this->escape(appUrl('/admin/services/save')) ?>">
    <input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>">
    <div class="form-grid"><div class="field"><label for="service-name">Service name *</label><input id="service-name" name="name" maxlength="150" value="<?= $this->escape($edit['name'] ?? '') ?>" required></div><div class="field"><label for="service-slug">URL slug *</label><input id="service-slug" name="slug" maxlength="190" value="<?= $this->escape($edit['slug'] ?? '') ?>" required></div></div>
    <div class="form-grid"><div class="field"><label for="service-icon">Lucide icon name</label><input id="service-icon" name="icon" maxlength="80" value="<?= $this->escape($edit['icon'] ?? 'sparkles') ?>" pattern="[A-Za-z0-9-]+"></div><div class="field"><label for="service-order">Sort order</label><input id="service-order" name="sort_order" type="number" step="1" value="<?= (int) ($edit['sort_order'] ?? 0) ?>"></div></div>
    <div class="field"><label for="service-summary">Short summary</label><textarea id="service-summary" name="summary" rows="2" maxlength="5000"><?= $this->escape($edit['summary'] ?? '') ?></textarea></div>
    <div class="field"><label for="service-description">Full description</label><textarea id="service-description" name="description" rows="5" maxlength="20000"><?= $this->escape($edit['description'] ?? '') ?></textarea></div>
    <div class="admin-form-footer"><label class="admin-checkbox"><input type="checkbox" name="is_active" value="1" <?= !isset($edit['is_active']) || (int) $edit['is_active'] === 1 ? 'checked' : '' ?>> Visible on the public site</label><button class="button" type="submit"><?= $edit ? 'Save service' : 'Add service' ?></button><?php if ($edit): ?><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/services')) ?>">Cancel</a><?php endif ?></div>
  </form>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Services</span><h2>Service catalog <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No services are configured.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Service</th><th>URL</th><th>Order</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['name']) ?></strong><small class="table-subtext"><?= $this->escape($record['summary'] ?: '') ?></small></td><td>/services/<?= $this->escape($record['slug']) ?></td><td><?= (int) $record['sort_order'] ?></td><td><span class="status-badge status-<?= (int) $record['is_active'] === 1 ? 'active' : 'inactive' ?>"><?= (int) $record['is_active'] === 1 ? 'Published' : 'Hidden' ?></span></td><td><a class="admin-icon-link" aria-label="Edit <?= $this->escape($record['name']) ?>" href="<?= $this->escape(appUrl('/admin/services?id=' . (int) $record['id'])) ?>"><i data-lucide="pencil"></i></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
